corrected_code:
router.post('/api/unleash/features/check', checkSession, async (req, res) => {
  const { featureNames } = req.body;
  const verifiedTenantId = req.user.tenantId;

  const results = {};
  for (const name of featureNames) {
    results[name] = unleashClient.isEnabled(name, {
      tenantId: verifiedTenantId,
      properties: { tenant: verifiedTenantId }
    });
  }

  res.json({ tenantId: verifiedTenantId, features: results });
});
